mapper.select:
SELECT USER_ID
FROM OP_SELLER_USER
WHERE LOGIN_ID = #{loginId}

/** seller-user-mapper.getPkiSellerFormValid (PKI 폼 유효성 조회) */ SELECT T_A.* , CRYPTO_DEC('normal', IFNULL(T_A.PHONE_NUMBER_ENC, '') , '', 0) AS PHONE_NUMBER FROM ( SELECT SU.USER_ID,
SU.MBER_DN, SU.MBER_FIN_DN,
IFNULL(S.PHONE_NUMBER, '') AS PHONE_NUMBER_ENC FROM OP_SELLER_USER SU , OP_SELLER S WHERE SU.STATUS_CODE = '9' AND S.STATUS_CODE = '2' AND SU.LOGIN_ID = S.LOGIN_ID AND SU.LOGIN_ID = #{loginId}
AND S.BUSINESS_NUMBER = #{businessNumber} AND S.PHONE_NUMBER = (SELECT CRYPTO_ENC('normal', #{phoneNumber}, '')) ) T_A

mapper.update:
UPDATE OP_SELLER_USER
	SET LOGIN_FAIL_COUNT = 0
WHERE LOGIN_ID = #{value}

UPDATE OP_SELLER_USER SU
	, OP_SELLER S
	SET SU.MBER_CI = (SELECT CRYPTO_ENC('normal', #{mberCi}, ''))
WHERE 	S.LOGIN_ID = #{loginId}
	AND SU.LOGIN_ID = S.LOGIN_ID
	AND SU.USER_ID = #{userId}

UPDATE OP_SELLER_USER
	SET MBER_CI = null
WHERE USER_ID = #{value}
